<?php
require_once __DIR__ . '/../core/bootstrap.php';
function dashboard_data() { $u = current_user(); $d = ['cards'=>[], 'recent'=>[], 'children'=>[], 'grades'=>[], 'chart'=>null, 'chart2'=>null]; try { if (in_array($u['role'], ['admin','secretaria','docente'], true)) { $d['cards'] = ['Estudiantes' => (new StudentModel())->count(), 'Usuarios' => (new UserModel())->count(), 'Comunicados' => db()->query('SELECT COUNT(*) c FROM announcements')->fetch()['c'], 'Eventos' => db()->query('SELECT COUNT(*) c FROM calendar_events')->fetch()['c']]; $d['recent'] = db()->query("SELECT a.attendance_date, CONCAT(s.first_name,' ',s.last_name) estudiante, a.status FROM attendance a INNER JOIN students s ON s.id=a.student_id ORDER BY a.id DESC LIMIT 8")->fetchAll(); $am = new AttendanceModel(); $d['chart'] = $am->chart_monthly((int)date('Y')); } elseif ($u['role'] === 'padre') { $sm = new StudentModel(); $d['children'] = $sm->children_of($u['id']); foreach ($d['children'] as &$ch) $ch['recent_attendance'] = $sm->attendance_of($ch['id']); unset($ch); } elseif ($u['role'] === 'estudiante') { $sm = new StudentModel(); $st = $sm->by_user($u['id']); if ($st) { $d['recent'] = $sm->attendance_of($st['id']); $d['grades'] = $sm->grades_of($st['id']); } } } catch (Throwable $e) { flash('error', 'No se pudo cargar el panel: ' . $e->getMessage()); } return $d; }
